18	// ---------- Auth ----------
19	
20	const credsSchema = z.object({
21	  email: z.string().email().max(200),
22	  password: z.string().min(8).max(200),
23	});
24	
25	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
26	  const parsed = credsSchema.extend({ name: z.string().min(1).max(100) }).safeParse({
27	    email: formData.get("email"),
28	    password: formData.get("password"),
29	    name: formData.get("name"),
30	  });
31	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
32	  const { email, password, name } = parsed.data;
33	
34	  const existing = await db.user.findUnique({ where: { email } });
35	  if (existing) return { error: "An account with that email already exists." };
36	
37	  const user = await db.user.create({
38	    data: { email, name, passwordHash: await bcrypt.hash(password, 12) },
39	  });
40	  await audit(user.id, "user.register");
41	  try {
42	    const { sendMail, emails } = await import("./mailer");
43	    const tpl = emails.welcome(name);
44	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
45	  } catch { /* email is best-effort */ }
46	  await createSession(user.id);
47	  redirect("/dashboard");
48	}
