50	export async function login(prev: any, formData: FormData): Promise<{ error?: string }> {
51	  const parsed = credsSchema.safeParse({
52	    email: formData.get("email"),
53	    password: formData.get("password"),
54	  });
55	  if (!parsed.success) return { error: "Invalid email or password." };
56	
57	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
58	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
59	    return { error: "Invalid email or password." };
60	  }
61	  if (user.suspended) return { error: "This account is suspended." };
62	  await audit(user.id, "user.login");
63	  await createSession(user.id);
64	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
65	}
