72	// ---------- Ordering ----------
73	
74	const orderSchema = z.object({
75	  planId: z.string().min(1),
76	  osTemplateId: z.string().min(1),
77	  hostname: z
78	    .string()
79	    .min(3)
80	    .max(40)
81	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
82	});
