104	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
105	  const user = await requireUser();
106	  const parsed = orderSchema.safeParse({
107	    planId: formData.get("planId"),
108	    osTemplateId: formData.get("osTemplateId"),
109	    hostname: formData.get("hostname"),
110	  });
111	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
112	
113	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
114	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
115	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
116	
117	  // Image requirements (control panels/apps need more resources)
118	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
119	    return {
120	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
121	    };
122	  }
123	
124	  const cap = await capacityCheck(plan.id);
125	  if (!cap.ok) return { error: cap.reason };
126	
127	  // Optional: node (location) selection, else auto-schedule
128	  const requestedNodeId = String(formData.get("nodeId") ?? "");
129	  let nodeId: string | null = null;
130	  if (requestedNodeId) {
131	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
132	    if (!n) return { error: "Selected location is not available." };
133	    nodeId = n.id;
134	  } else {
135	    const n = await scheduleNode(plan.ramMB);
136	    nodeId = n?.id ?? null;
137	  }
138	
139	  // Add-ons (booleans)
140	  const addons = {
141	    malwareScanner: formData.get("addon_malware") === "1",
142	    dailyBackup: formData.get("addon_backup") === "1",
143	    docker: formData.get("addon_docker") === "1",
144	  };
145	
146	  // Optional SSH key added at deploy time
147	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
148	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
149	
150	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
151	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
152	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
153	  const ipCents = wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0;
154	  const chargeCents = vpsTermPriceCents(plan.priceCents, term.months) + ipCents;
155	
156	  const isAdmin = user.role === "ADMIN";
157	  const freeRequested = formData.get("free") === "1" && isAdmin;
158	
159	  if (!freeRequested && user.balanceCents < chargeCents) {
160	    return { error: "Insufficient balance. Top up your wallet first." };
161	  }
162	
163	  let server;
164	  try {
165	    server = await db.$transaction(async (tx) => {
166	    if (!freeRequested) {
167	      await debitWallet(tx, user.id, chargeCents);
168	      await tx.walletTransaction.create({
169	        data: {
170	          userId: user.id,
171	          amountCents: -chargeCents,
172	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}`,
173	        },
174	      });
175	    }
176	    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
177	      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
178	      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
179	    }
180	    const s = await tx.server.create({
181	      data: {
182	        name: parsed.data.hostname,
183	        hostname: parsed.data.hostname,
184	        userId: user.id,
185	        planId: plan.id,
186	        osTemplateId: os.id,
187	        nodeId,
188	        addons,
189	        termMonths: term.months,
190	        wantsDedicatedIp,
191	        isFree: freeRequested,
192	        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
193	      },
194	    });
195	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
196	    return s;
197	    });
198	  } catch (e) {
199	    if (e instanceof InsufficientBalanceError) {
200	      return { error: "Insufficient balance. Top up your wallet first." };
201	    }
202	    throw e;
203	  }
204	
205	  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
206	  redirect(`/dashboard/servers/${server.id}`);
207	}
