209	// ---------- Server lifecycle ----------
210	
211	async function ownedServer(serverId: string) {
212	  const user = await requireUser();
213	  const server = await db.server.findUnique({ where: { id: serverId } });
214	  if (!server) throw new Error("Not found");
215	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
216	  return { user, server };
217	}
218	
219	export async function serverAction(serverId: string, action: string) {
220	  const { user, server } = await ownedServer(serverId);
221	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
222	    start: "START",
223	    stop: "STOP",
224	    reboot: "REBOOT",
225	    reinstall: "REINSTALL",
226	    delete: "DELETE",
227	  };
228	  const type = allowed[action];
229	  if (!type) throw new Error("Invalid action");
230	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
231	    throw new Error("Server is suspended");
232	  }
233	
234	  const pending = await db.job.count({
235	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
236	  });
237	  if (pending > 0) return; // debounce: one job at a time per server
238	
239	  if (type === "DELETE") {
240	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
241	  }
242	  await db.job.create({ data: { type, serverId } });
243	  await audit(user.id, `server.${action}`, serverId);
244	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
245	  revalidatePath(`/dashboard/servers/${serverId}`);
246	}
