248	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
249	
250	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
251	  const user = await requireUser();
252	  // Security: never credit a wallet without a real payment. Once Stripe is
253	  // configured, the demo gateway is hard-disabled — top-ups must go through Checkout.
254	  const { stripeConfigured } = await import("./stripe");
255	  if (stripeConfigured()) {
256	    return { error: "Please add funds with a card via the secure checkout." };
257	  }
258	  const amount = Number(formData.get("amount"));
259	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
260	    return { error: "Amount must be between $1 and $1000." };
261	  }
262	  const cents = Math.round(amount * 100);
263	  await db.$transaction([
264	    db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: cents } } }),
265	    db.walletTransaction.create({
266	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
267	    }),
268	  ]);
269	  await audit(user.id, "wallet.topup", `$${amount}`);
270	  revalidatePath("/dashboard/billing");
271	  return {};
272	}
