287	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
288	  const { user, server } = await ownedServer(serverId);
289	  if (server.isFree || !server.expiresAt) return;
290	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
291	  if (!plan) return;
292	  const term = vpsTerm(server.termMonths);
293	  const renewCents =
294	    vpsTermPriceCents(plan.priceCents, term.months) +
295	    (server.wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0);
296	  const owner = await db.user.findUnique({ where: { id: server.userId } });
297	  if (!owner || owner.balanceCents < renewCents) {
298	    return { error: "Insufficient balance — top up your wallet first." };
299	  }
300	
301	  const base = new Date(Math.max(server.expiresAt.getTime(), Date.now()));
302	  try {
303	    await db.$transaction(async (tx) => {
304	      await debitWallet(tx, server.userId, renewCents);
305	      await tx.walletTransaction.create({
306	        data: {
307	          userId: server.userId,
308	          amountCents: -renewCents,
309	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
310	        },
311	      });
312	      await tx.server.update({
313	        where: { id: serverId },
314	        data: { expiresAt: addMonths(base, term.months), suspendedNote: null },
315	      });
316	    });
317	  } catch (e) {
318	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
319	    throw e;
320	  }
321	  await audit(user.id, "server.renew_now", serverId);
322	
323	  // Unpaid-suspended server springs back to life once paid
324	  if (server.status === "SUSPENDED") {
325	    const pending = await db.job.count({
326	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
327	    });
328	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
329	  }
330	  revalidatePath(`/dashboard/servers/${serverId}`);
331	}
