335	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
336	  const admin = await requireAdmin();
337	  const serverId = String(formData.get("serverId") ?? "");
338	  const days = Number(formData.get("days"));
339	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
340	    return { error: "Days must be between -365 and 365." };
341	  }
342	  const server = await db.server.findUnique({ where: { id: serverId } });
343	  if (!server) return { error: "Server not found." };
344	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
345	  await db.server.update({
346	    where: { id: serverId },
347	    data: { expiresAt: new Date(base + days * 86400_000) },
348	  });
349	  await audit(admin.id, "admin.extend_server", `${serverId} ${days}d`);
350	  revalidatePath("/admin/subscriptions");
351	  return {};
352	}
