import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { stripe, stripeConfigured } from "@/lib/stripe";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars < 5 || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Nxeon wallet credit" },
          unit_amount: Math.round(dollars * 100),
        },
        quantity: 1,
      },
    ],
    metadata: { nxeonUserId: user.id },
    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}/dashboard/billing?canceled=1`,
  });
  return NextResponse.json({ url: session.url });
}
