// Plain (non-"use server") module for the growth engine: constants, env getters
// and pure helpers shared by server actions and pages. Safe to import from any
// server module. Do NOT import this from client components — it pulls in `crypto`.

import { randomInt } from "crypto";
import type { CouponKind } from "@prisma/client";

/**
 * Reward (in cents) granted to BOTH the referrer and the referred user when the
 * referred user completes their first successful paid action. Env override:
 * REFERRAL_REWARD_CENTS. Defaults to 500 ($5.00).
 */
export function referralRewardCents(): number {
  const n = Number(process.env.REFERRAL_REWARD_CENTS);
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 500;
}

/**
 * Free wallet credit (in cents) granted on signup. Env override:
 * SIGNUP_FREE_CREDIT_CENTS. Defaults to 0 (feature off).
 */
export function signupFreeCreditCents(): number {
  const n = Number(process.env.SIGNUP_FREE_CREDIT_CENTS);
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 0;
}

// Unambiguous alphabet (no 0/O/1/I/L) for human-shareable referral codes.
const CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";

/** Generate a random, unambiguous referral code (uppercase). Uniqueness must be
 *  enforced by the caller against the DB. */
export function generateReferralCode(length = 7): string {
  let out = "";
  for (let i = 0; i < length; i++) out += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)];
  return out;
}

/** Human-readable summary of what a coupon grants, e.g. "20% bonus", "$5.00 credit". */
export function describeCoupon(coupon: { kind: CouponKind; value: number }): string {
  switch (coupon.kind) {
    case "PERCENT":
      return `${coupon.value}% bonus`;
    case "FIXED_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} off`;
    case "CREDIT_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} credit`;
    default:
      return "discount";
  }
}

"use server";

import { z } from "zod";
import type { Coupon } from "@prisma/client";
import { db } from "./db";
import { requireUser, requireAdmin } from "./auth";
import {
  describeCoupon,
  referralRewardCents,
  signupFreeCreditCents,
} from "./growth";

// ---------- Coupons ----------

export type CouponApplyResult =
  | {
      ok: true;
      couponId: string;
      code: string;
      /** Extra wallet credit (in cents) the user receives on top of the amount added. */
      bonusCents: number;
      /** Human-readable summary, e.g. "20% bonus". */
      label: string;
    }
  | { ok: false; error: string };

/**
 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
 */
function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
  switch (coupon.kind) {
    case "PERCENT":
      return Math.round((baseCents * coupon.value) / 100);
    case "FIXED_CENTS":
    case "CREDIT_CENTS":
      return coupon.value;
    default:
      return 0;
  }
}

/**
 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
 * return the bonus that would be credited. Read-only: it never mutates state,
 * so it is safe to call both for the live preview (CouponField) and again inside
 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
 */
export async function applyCouponToTopup(
  code: string,
  baseCents: number
): Promise<CouponApplyResult> {
  const user = await requireUser();
  const normalized = String(code ?? "").trim().toUpperCase();
  if (!normalized) return { ok: false, error: "Enter a promo code." };

  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.scope === "ORDER") {
    return { ok: false, error: "This code only applies to server orders." };
  }
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
    return { ok: false, error: "This code has expired." };
  }
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "This code has reached its redemption limit." };
  }
  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
    return {
      ok: false,
      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
    };
  }

  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
  const already = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
  });
  if (already) return { ok: false, error: "You’ve already used this code." };

  if (coupon.firstTimeOnly) {
    // "First-time" = the user has never received a positive wallet credit before.
    const priorCredits = await db.walletTransaction.count({
      where: { userId: user.id, amountCents: { gt: 0 } },
    });
    if (priorCredits > 0) {
      return { ok: false, error: "This code is for first-time customers only." };
    }
  }

  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
  return {
    ok: true,
    couponId: coupon.id,
    code: coupon.code,
    bonusCents,
    label: describeCoupon(coupon),
  };
}

// ---------- Admin: coupon management ----------

const couponSchema = z.object({
  code: z
    .string()
    .trim()
    .min(3)
    .max(32)
    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
  value: z.coerce.number().int().min(1).max(1_000_000),
  firstTimeOnly: z.coerce.boolean(),
  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
  expiresAt: z.string().optional(),
  note: z.string().max(200).optional(),
});

export async function adminCreateCoupon(
  prev: any,
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireAdmin();
  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
  const parsed = couponSchema.safeParse({
    code: formData.get("code"),
    kind: formData.get("kind"),
    scope: formData.get("scope"),
    value: formData.get("value"),
    firstTimeOnly: formData.get("firstTimeOnly") === "on",
    minAmountCents: rawMin === "" ? undefined : rawMin,
    maxRedemptions: rawMax === "" ? undefined : rawMax,
    expiresAt: rawExpires === "" ? undefined : rawExpires,
    note: formData.get("note") || undefined,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
  }
  const data = parsed.data;
  if (data.kind === "PERCENT" && data.value > 100) {
    return { error: "Percent value must be between 1 and 100." };
  }
  const code = data.code.toUpperCase();

  const existing = await db.coupon.findUnique({ where: { code } });
  if (existing) return { error: "A coupon with that code already exists." };

  let expiresAt: Date | null = null;
  if (data.expiresAt) {
    const d = new Date(data.expiresAt);
    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
    expiresAt = d;
  }

  await db.coupon.create({
    data: {
      code,
      kind: data.kind,
      scope: data.scope,
      value: data.value,
      firstTimeOnly: data.firstTimeOnly,
      minAmountCents: data.minAmountCents ?? null,
      maxRedemptions: data.maxRedemptions ?? null,
      expiresAt,
      note: data.note ?? null,
    },
  });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
  });
  return { ok: true };
}

export async function adminToggleCoupon(id: string): Promise<void> {
  const admin = await requireAdmin();
  const coupon = await db.coupon.findUnique({ where: { id } });
  if (!coupon) return;
  await db.coupon.update({ where: { id }, data: { active: !coupon.active } });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "admin.coupon_toggle",
      detail: `${coupon.code} -> ${!coupon.active ? "active" : "inactive"}`,
    },
  });
}

export async function adminDeleteCoupon(id: string): Promise<void> {
  const admin = await requireAdmin();
  const coupon = await db.coupon.findUnique({ where: { id } });
  if (!coupon) return;
  await db.coupon.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.coupon_delete", detail: coupon.code },
  });
}

// ---------- Signup free credit ----------

/**
 * Grant the configured signup free credit to a freshly-registered user, once.
 * No-op when SIGNUP_FREE_CREDIT_CENTS is 0 or the user already has signup credit.
 * Callable from `register` in lib/actions.ts.
 */
export async function grantSignupCredit(userId: string): Promise<number> {
  const cents = signupFreeCreditCents();
  if (cents <= 0) return 0;
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || user.signupCreditCents > 0) return 0;
  await db.$transaction([
    db.user.update({
      where: { id: userId },
      data: { balanceCents: { increment: cents }, signupCreditCents: cents },
    }),
    db.walletTransaction.create({
      data: { userId, amountCents: cents, description: "Welcome credit" },
    }),
  ]);
  return cents;
}

// ---------- Referral rewards ----------

/**
 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
 */
export async function maybeRewardReferral(userId: string): Promise<boolean> {
  const reward = referralRewardCents();
  if (reward <= 0) return false;

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || !user.referredById || user.referralRewardedAt) return false;
  const referrerId = user.referredById;

  // Atomically claim the reward; if another concurrent action already did, bail.
  const claim = await db.user.updateMany({
    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
    data: { referralRewardedAt: new Date() },
  });
  if (claim.count === 0) return false;

  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
    db.walletTransaction.create({
      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
    }),
    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
    db.walletTransaction.create({
      data: {
        userId: referrerId,
        amountCents: reward,
        description: "Referral bonus — you referred a friend",
      },
    }),
  ]);

  // Best-effort in-app notifications.
  try {
    await db.notification.createMany({
      data: [
        {
          userId,
          title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
          href: "/dashboard/billing",
        },
        {
          userId: referrerId,
          title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
          href: "/dashboard/refer",
        },
      ],
    });
  } catch {
    /* best-effort */
  }
  return true;
}

