      <div className="flex flex-wrap items-center gap-2 text-sm text-slate-400">
        <span>Your code:</span>
        <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-0.5 font-mono text-brand-200">
          {code}
        </span>
      </div>

      <div className="grid grid-cols-2 gap-4 border-t border-white/[0.06] pt-4">
        <div>
          <p className="text-2xl font-bold">{referredCount}</p>
          <p className="text-xs text-slate-500">Friends signed up</p>
        </div>
        <div>
          <p className="text-2xl font-bold text-emerald-400">{rewardedCount}</p>
          <p className="text-xs text-slate-500">Rewarded referrals</p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useActionState, useEffect, useRef, useTransition } from "react";
import { adminCreateCoupon, adminToggleCoupon, adminDeleteCoupon } from "@/lib/actions-growth";

export function CouponCreateForm() {
  const [state, action, pending] = useActionState(adminCreateCoupon, {} as { error?: string; ok?: boolean });
