  useEffect(() => {
    if (state?.ok) formRef.current?.reset();
  }, [state]);

  return (
    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Coupon created.
        </div>
      )}
      <div>
        <label className="label">Code</label>
        <input className="input uppercase" name="code" placeholder="WELCOME10" required />
      </div>
      <div>
        <label className="label">Type</label>
        <select className="input" name="kind" defaultValue="PERCENT">
          <option value="PERCENT">Percent bonus</option>
          <option value="FIXED_CENTS">Fixed cents off</option>
          <option value="CREDIT_CENTS">Flat credit (cents)</option>
        </select>
      </div>
      <div>
        <label className="label">Value</label>
        <input className="input" name="value" type="number" min={1} placeholder="10 or 500" required />
        <p className="mt-1 text-[11px] text-slate-500">% for percent, cents otherwise</p>
      </div>
      <div>
        <label className="label">Scope</label>
        <select className="input" name="scope" defaultValue="TOPUP">
          <option value="ANY">Any</option>
          <option value="TOPUP">Top-up only</option>
          <option value="ORDER">Order only</option>
        </select>
      </div>
      <div>
        <label className="label">Min amount (cents)</label>
        <input className="input" name="minAmountCents" type="number" min={0} placeholder="optional" />
      </div>
      <div>
        <label className="label">Max redemptions</label>
        <input className="input" name="maxRedemptions" type="number" min={1} placeholder="optional" />
      </div>
      <div>
        <label className="label">Expires</label>
        <input className="input" name="expiresAt" type="date" />
      </div>
      <div>
        <label className="label">Note</label>
        <input className="input" name="note" placeholder="internal note" maxLength={200} />
      </div>
      <div className="col-span-full flex items-center gap-4">
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" name="firstTimeOnly" /> First-time customers only
        </label>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Creating…" : "Create coupon"}
        </button>
      </div>
    </form>
  );
}

export function ToggleCouponButton({ id, active }: { id: string; active: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
      disabled={pending}
      onClick={() => start(() => adminToggleCoupon(id))}
    >
      {active ? "Disable" : "Enable"}
    </button>
  );
}

export function DeleteCouponButton({ id, code }: { id: string; code: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-danger py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (confirm(`Delete coupon ${code}? This also removes its redemption records.`)) {
          start(() => adminDeleteCoupon(id));
        }
      }}
    >
      Delete
    </button>
  );
}

