import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, fmtMoney } from "@/components/ui/primitives";
import { ReferralPanel } from "@/components/customer/ReferralPanel";
import { referralRewardCents, generateReferralCode } from "@/lib/growth";

export const dynamic = "force-dynamic";

async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
  if (current) return current;
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (clash) continue;
    try {
      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
      return code;
    } catch {
      /* unique clash race — retry */
    }
  }
  const fallback = generateReferralCode(12);
  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
  return fallback;
}

export default async function ReferPage() {
  const user = await requireUser();
  const code = await ensureReferralCode(user.id, user.referralCode);

  const [referredCount, rewardedCount] = await Promise.all([
    db.user.count({ where: { referredById: user.id } }),
    db.user.count({ where: { referredById: user.id, referralRewardedAt: { not: null } } }),
  ]);

  const rewardCents = referralRewardCents();
  const appUrl = (process.env.APP_URL ?? "https://revsports.ca").replace(/\/+$/, "");
  const link = `${appUrl}/register?ref=${code}`;

  return (
    <div className="space-y-6">
      <PageHeader title="Refer & earn" sub="Invite friends and you both get wallet credit." />

      <ReferralPanel
        link={link}
        code={code}
        rewardLabel={fmtMoney(rewardCents)}
        referredCount={referredCount}
        rewardedCount={rewardedCount}
      />

      <div className="card">
        <p className="section-label mb-4">How it works</p>
        <ol className="space-y-3 text-sm text-slate-400">
          <li className="flex gap-3">
            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
              1
            </span>
            Share your personal referral link with friends and colleagues.
          </li>
          <li className="flex gap-3">
            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
              2
            </span>
            They create an account through your link.
          </li>
          <li className="flex gap-3">
            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
              3
            </span>
            When they make their first payment (a wallet top-up or a server order),
            you&apos;re <span className="text-slate-200">both</span> credited{" "}
            <span className="font-semibold text-brand-300">{fmtMoney(rewardCents)}</span>{" "}
            automatically.
          </li>
        </ol>
      </div>
    </div>
  );
}

import { db } from "@/lib/db";
