export const dynamic = "force-dynamic";

function scopeLabel(scope: string): string {
  return scope === "TOPUP" ? "Top-up" : scope === "ORDER" ? "Order" : "Any";
}

export default async function AdminCoupons() {
  await requireArea("billing");
  const coupons = await db.coupon.findMany({ orderBy: { createdAt: "desc" } });

  return (
    <div className="space-y-6">
      <PageHeader title="Coupons" sub="Promo codes customers redeem on wallet top-up." />

      <div className="card">
        <p className="section-label mb-4">Create coupon</p>
        <CouponCreateForm />
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">All coupons</p>
        {coupons.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No coupons yet — create one above.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[820px]">
            <thead>
              <tr>
                <th>Code</th>
                <th>Reward</th>
                <th>Scope</th>
                <th>Rules</th>
                <th className="text-right">Redeemed</th>
                <th>Expires</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {coupons.map((c) => {
                const expired = c.expiresAt !== null && c.expiresAt.getTime() < Date.now();
                return (
                  <tr key={c.id}>
                    <td className="font-mono text-sm">{c.code}</td>
                    <td>{describeCoupon(c)}</td>
                    <td className="text-slate-400">{scopeLabel(c.scope)}</td>
                    <td className="text-xs text-slate-400">
                      {c.firstTimeOnly && <span className="mr-2">first-time</span>}
                      {c.minAmountCents !== null && (
                        <span className="mr-2">min {fmtMoney(c.minAmountCents)}</span>
                      )}
                      {c.note && <span className="text-slate-500">· {c.note}</span>}
                    </td>
                    <td className="text-right font-mono text-sm text-slate-300">
                      {c.timesRedeemed}
                      {c.maxRedemptions !== null ? ` / ${c.maxRedemptions}` : ""}
                    </td>
                    <td className="text-xs text-slate-400">
                      {c.expiresAt ? c.expiresAt.toISOString().slice(0, 10) : "—"}
                    </td>
                    <td>
                      {!c.active ? (
                        <Badge tone="slate">disabled</Badge>
                      ) : expired ? (
                        <Badge tone="amber">expired</Badge>
                      ) : (
                        <Badge tone="green">active</Badge>
                      )}
                    </td>
                    <td>
                      <div className="flex items-center justify-end gap-2">
                        <ToggleCouponButton id={c.id} active={c.active} />
                        <DeleteCouponButton id={c.id} code={c.code} />
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

